// ─────────────────────────────────────────────────────────────────────────────
// Constructor
// ─────────────────────────────────────────────────────────────────────────────
WiFiProvisioning::WiFiProvisioning()
    : _server(80), _apMode(false), _credentialsSaved(false) {}

// ─────────────────────────────────────────────────────────────────────────────
// NVS Helpers
// ─────────────────────────────────────────────────────────────────────────────
bool WiFiProvisioning::hasCredentials() {
  _prefs.begin(NVS_NS, true); // read-only
  bool result =
      _prefs.isKey("ssid") && _prefs.getString("ssid", "").length() > 0;
  _prefs.end();
  return result;
}

String WiFiProvisioning::getSSID() {
  _prefs.begin(NVS_NS, true);
  String val = _prefs.getString("ssid", "");
  _prefs.end();
  return val;
}

String WiFiProvisioning::getPassword() {
  _prefs.begin(NVS_NS, true);
  String val = _prefs.getString("password", "");
  _prefs.end();
  return val;
}

String WiFiProvisioning::getOcppUrl() {
  _prefs.begin(NVS_NS, true);
  String val = _prefs.getString("ocppUrl", DEFAULT_OCPP_URL);
  _prefs.end();
  return val;
}

String WiFiProvisioning::getChargePointId() {
  _prefs.begin(NVS_NS, true);
  String val = _prefs.getString("cpId", DEFAULT_CP_ID);
  _prefs.end();
  return val;
}

float WiFiProvisioning::getSctCalibration() {
  _prefs.begin(NVS_NS, true);
  float val = _prefs.getFloat("sctCal", DEFAULT_SCT_CAL);
  _prefs.end();
  return val;
}

bool WiFiProvisioning::getAutocutEnabled() {
  _prefs.begin(NVS_NS, true);
  bool val = _prefs.getBool("autocutOn", DEFAULT_AUTOCUT);
  _prefs.end();
  return val;
}

void WiFiProvisioning::saveCredentials(const String &ssid,
                                       const String &password,
                                       const String &ocppUrl,
                                       const String &cpId,
                                       float sctCalibration,
                                       bool autocutEnabled) {
  _prefs.begin(NVS_NS, false);
  _prefs.putString("ssid", ssid);
  _prefs.putString("password", password);
  _prefs.putString("ocppUrl",
                   ocppUrl.length() > 0 ? ocppUrl : DEFAULT_OCPP_URL);
  _prefs.putString("cpId", cpId.length() > 0 ? cpId : DEFAULT_CP_ID);
  _prefs.putFloat("sctCal", (sctCalibration > 0.0f) ? sctCalibration : DEFAULT_SCT_CAL);
  _prefs.putBool("autocutOn", autocutEnabled);
  _prefs.end();
  Serial.printf("[NVS] Guardado — SSID: %s | SCT: %.1f | Autocut: %s\n",
                ssid.c_str(), sctCalibration, autocutEnabled ? "ON" : "OFF");
}

void WiFiProvisioning::clearCredentials() {
  _prefs.begin(NVS_NS, false);
  _prefs.clear();
  _prefs.end();
  Serial.println("[NVS] Credenciales borradas (factory reset)");
}

// ─────────────────────────────────────────────────────────────────────────────
// AP Mode + Captive Portal
// ─────────────────────────────────────────────────────────────────────────────
void WiFiProvisioning::startAPMode() {
  _apMode = true;
  _credentialsSaved = false;

  // Start AP (no password = open network, easier for first contact)
  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_SSID);

  IPAddress apIP(192, 168, 4, 1);
  WiFi.softAPConfig(apIP, apIP, IPAddress(255, 255, 255, 0));

  Serial.printf("[AP] Red WiFi: '%s'\n", AP_SSID);
  Serial.printf("[AP] Portal:   http://%s\n", apIP.toString().c_str());

  // DNSServer: redirect all DNS queries to our IP (captive portal magic)
  _dns.start(53, "*", apIP);

  _setupRoutes();
  _server.begin();

  Serial.println("[AP] Servidor HTTP listo en puerto 80");
}

void WiFiProvisioning::_setupRoutes() {
  // Main config page
  _server.on("/", HTTP_GET, [this]() { _handleRoot(); });
  _server.on("/save", HTTP_POST, [this]() { _handleSave(); });

  // Captive portal detection — iOS, Android, Windows redirect to our page
  _server.on("/hotspot-detect.html", HTTP_GET,
             [this]() { _handleCaptiveRedirect(); });
  _server.on("/library/test/success.html", HTTP_GET,
             [this]() { _handleCaptiveRedirect(); });
  _server.on("/generate_204", HTTP_GET, [this]() { _handleCaptiveRedirect(); });
  _server.on("/gen_204", HTTP_GET, [this]() { _handleCaptiveRedirect(); });
  _server.on("/ncsi.txt", HTTP_GET, [this]() { _handleCaptiveRedirect(); });
  _server.on("/connecttest.txt", HTTP_GET,
             [this]() { _handleCaptiveRedirect(); });
  _server.on("/redirect", HTTP_GET, [this]() { _handleCaptiveRedirect(); });
  _server.on("/success.txt", HTTP_GET, [this]() { _handleCaptiveRedirect(); });

  // Catch-all: redirect everything else to the config page
  _server.onNotFound([this]() { _handleCaptiveRedirect(); });

  // Status endpoint (JSON)
  _server.on("/status", HTTP_GET, [this]() {
    String json = "{";
    json += "\"ap\":\"" + String(AP_SSID) + "\",";
    json += "\"uptime\":" + String(millis() / 1000) + ",";
    json += "\"free_heap\":" + String(ESP.getFreeHeap());
    json += "}";
    _server.send(200, "application/json", json);
  });
}

void WiFiProvisioning::_handleRoot() {
  // Inject saved NVS values into the HTML template
  String page = String(HTML_SETUP);
  
  _prefs.begin(NVS_NS, true);
  String savedUrl = _prefs.getString("ocppUrl", DEFAULT_OCPP_URL);
  String savedCpId = _prefs.getString("cpId", DEFAULT_CP_ID);
  float savedSctCal = _prefs.getFloat("sctCal", DEFAULT_SCT_CAL);
  bool savedAutocut = _prefs.getBool("autocutOn", true);
  _prefs.end();
  
  page.replace("__OCPP_URL__", savedUrl);
  page.replace("__CP_ID__", savedCpId);
  page.replace("__SCT_CAL__", String(savedSctCal, 1));
  page.replace("__AUTOCUT_CHECKED__", savedAutocut ? "checked" : "");
  page.replace("__FIRMWARE_VERSION__", FIRMWARE_VERSION);
  
  _server.send(200, "text/html", page);
}

void WiFiProvisioning::_handleSave() {
  String ssid = _server.arg("ssid");
  String password = _server.arg("password");
  String ocppUrl = _server.arg("ocppUrl");
  String cpId = _server.arg("cpId");
  float sctCal = _server.arg("sctCal").toFloat();
  bool autocutEnabled = (_server.arg("autocutEnabled") == "1");

  if (ssid.length() == 0) {
    _server.send(400, "text/plain", "Error: SSID requerido");
    return;
  }

  String resetMetrics = _server.arg("resetMetrics");
  if (resetMetrics == "1") {
    Preferences energyPrefs;
    energyPrefs.begin("fluxio-meter", false);
    energyPrefs.putFloat("total_kwh", 0.0f);
    energyPrefs.end();
    Serial.println("[NVS] Métricas de energía reiniciadas a 0.0 kWh");
  }

  saveCredentials(ssid, password, ocppUrl, cpId, sctCal, autocutEnabled);
  _server.send_P(200, "text/html", HTML_SUCCESS);
  _credentialsSaved = true;
}

void WiFiProvisioning::_handleCaptiveRedirect() {
  _server.sendHeader("Location", "http://192.168.4.1/", true);
  _server.send(302, "text/plain", "");
}

bool WiFiProvisioning::handleAPLoop() {
  _dns.processNextRequest();
  _server.handleClient();
  return _credentialsSaved;
}
